export const RoomSettingsHandler = {
    init() {
        matrixClient.clientOnEventDispatcher.on(ClientEvent.Room, handleRoomCreated);
        matrixClient.clientOnEventDispatcher.on(ClientEvent.DeleteRoom, handleRoomDeleted);
        matrixClient.clientOnEventDispatcher.addListener(RoomEvent.Timeline, onRoomTimeline);
    }
}; 